\title{Gradient Descent in the Tropical Limit:\\
Sharpness, Dequantization, and Linear Convergence\\ for Max-Plus Learning}
\author{Aristotle}
\date{16 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete first-order learning theory for exp--log neural units in their
tropical, or large-weight, limit. Three strands are combined. First, we quantify Maslov
dequantization: a smooth log-sum-exp aggregator at temperature $T$ over $k$ terms differs
from the corresponding max-plus fold by at most $T\log k$, uniformly in the input, so that
an exp--log neuron converges to a tropical polynomial as $T\to 0^{+}$ (equivalently as the
weight scale $s=1/T\to\infty$). Second, we prove an exact dictionary in one variable: a
function $\R\to\R$ is a tropical rational function --- a difference of two finite maxima of
affine functions --- if and only if it is computed by a feed-forward rectifier network of
arbitrary depth; both inclusions are given by explicit constructions in which each tropical
monomial costs exactly one rectifier unit. Third, we analyse training. The tropical
absolute-error empirical risk of a max-plus monomial is itself a tropical polynomial in the
parameter, convex, $N$-Lipschitz, and \emph{sharp}: on an ordered odd sample of size
$N=2m+1$ it satisfies $R(\theta)\ge R(\theta^\star)+|\theta-\theta^\star|$ with
$\theta^\star$ the median residual, which is therefore the unique empirical risk minimizer.
Fixed-step subgradient descent attains the optimal general rate $O(DG/\sqrt n)$ in risk and,
by sharpness, the same rate in parameter error, with $G=N$. Sharpness further yields a
genuinely faster regime: subgradient descent with Polyak steps contracts the squared distance
to the optimum by the factor $1-\mu^2/G^2$ per iteration, giving
$(\theta_n-\theta^\star)^2\le(1-1/N^2)^n(\theta_0-\theta^\star)^2$, together with convergence
of the trained model to a tropical rational minimizer. The boundary of the theory is sharp:
an explicit three-sample instance exhibits an exact two-cycle under a fixed step, so the
iterates never come within distance $2$ of the unique minimizer. Finally, a risk-landscape
equivalence shows that a function is tropical rational precisely when some rectifier network
has the same empirical risk on \emph{every} data set; hence the speed of first-order training
is governed not by the parameterization but by two tropical invariants, the maximal slope $G$
and the sharpness constant $\mu$.
\end{abstract}

\noindent\textbf{Keywords:} tropical geometry, max-plus algebra, Maslov dequantization,
rectifier networks, subgradient methods, sharpness, Polyak step size, piecewise-linear
optimization.

\section{Introduction}

\subsection{Motivation}

Neural networks built from rectifier nonlinearities compute piecewise-linear functions. This
is not an approximation but an identity. Consequently the apparatus of smooth optimization
--- gradients, Hessians, strong convexity, smoothness constants --- sits uneasily on the
actual object being optimized, which has no second derivative anywhere and no first
derivative on a codimension-one set.

Tropical geometry supplies the native language. In the max-plus semiring
$(\R\cup\{-\infty\},\oplus,\odot)$ with $a\oplus b=\max(a,b)$ and $a\odot b=a+b$, a polynomial
is a finite maximum of affine functions and a rational function is a difference of two such
maxima. The class of tropical rational functions in one variable is exactly the class of
continuous piecewise-linear functions with finitely many pieces. What we supply here are
explicit constructive translations between tropical rational functions and rectifier networks
with a tight accounting of cost (one rectifier per tropical monomial), and --- more
importantly --- a \emph{training theory} stated entirely in tropical invariants.

A second motivation is the ubiquity of smooth exp--log aggregators. Write
\[
  \LSE_T(u_1,\dots,u_k)\;=\;T\log\Bigl(\sum_{j=1}^{k}e^{u_j/T}\Bigr).
\]
At $T=1$ this is the log-partition function; softmax attention, mixture gating and
energy-based blending are all instances. Here $T$ is a temperature and $s=1/T$ the overall
weight scale. In the large-weight regime $s\to\infty$ the aggregator degenerates to
$\max_j u_j$: Maslov dequantization, the semiring shadow of the zero-temperature limit of
statistical mechanics. Our first task is to make it quantitative and uniform.

\subsection{Contributions}

\begin{enumerate}
\item \textbf{Quantitative dequantization} (Section~\ref{sec:deq}): two-sided bounds
$\max_j u_j\le\LSE_T\le\max_j u_j+T\log k$; hence uniform-in-input approximation of an
exp--log neuron by a tropical polynomial with error $T\log k$.
\item \textbf{The tropical/rectifier dictionary} (Section~\ref{sec:dict}): $f:\R\to\R$ is
tropical rational iff a rectifier expression computes it, constructively in both directions.
\item \textbf{Sharpness of the tropical risk} (Section~\ref{sec:sharp}):
$R(\theta)\ge R(\theta^\star)+|\theta-\theta^\star|$ for ordered odd samples, with
$\theta^\star$ the median; uniqueness of the minimizer follows.
\item \textbf{Rates} (Sections~\ref{sec:fixed}--\ref{sec:polyak}): the $O(DG/\sqrt n)$
best-iterate bound with $G=N$; automatic transfer to parameter error; and a geometric rate
$1-\mu^2/G^2$ per Polyak step, instantiated as $1-1/N^2$.
\item \textbf{A negative result} (Section~\ref{sec:cycle}): an exact two-cycle for a fixed
step.
\item \textbf{Landscape equivalence} (Section~\ref{sec:relu}): tropical rationality equals
having the same empirical risk as some rectifier network on every data set.
\end{enumerate}

\section{Setting and definitions}

Throughout, $\relu(u)=\max(u,0)$.

\begin{definition}[Max-plus fold]
For $b\in\R$ and a finite list $\ell=[y_1,\dots,y_r]$ of reals,
$\tmax(b;\ell)=\max\{b,y_1,\dots,y_r\}$, with $\tmax(b;[\,])=b$. This is the tropical sum
$b\oplus y_1\oplus\cdots\oplus y_r$; the base $b$ guarantees nonemptiness, so no $-\infty$ is
needed.
\end{definition}

\begin{definition}[Tropical polynomial function]
For $b=(b_1,b_2)\in\R^2$ and a finite list $\ell$ of pairs $t=(t_1,t_2)\in\R^2$, set
\[
  P_{b,\ell}(x)\;=\;\tmax\bigl(b_1x+b_2;\,[\,t_1x+t_2:t\in\ell\,]\bigr)
  \;=\;\max\Bigl(b_1x+b_2,\ \max_{t\in\ell}(t_1x+t_2)\Bigr).
\]
Each $(t_1,t_2)$ is a \emph{tropical monomial} with slope $t_1$ and coefficient $t_2$. A
function $f$ \emph{is a tropical polynomial} if $f=P_{b,\ell}$ for some $b,\ell$.
\end{definition}

\begin{definition}[Tropical rational function]
$f:\R\to\R$ is \emph{tropical rational} if $f=P-Q$ pointwise for tropical polynomials $P,Q$.
\end{definition}

\begin{definition}[Rectifier expressions]
Rectifier expressions are generated inductively by
$e ::= \mathrm{affine}(a,b)\mid e_1+e_2\mid c\cdot e\mid \mathrm{act}(e)$,
with semantics $\mathrm{affine}(a,b)(x)=ax+b$, $(e_1+e_2)(x)=e_1(x)+e_2(x)$,
$(c\cdot e)(x)=c\,e(x)$, $\mathrm{act}(e)(x)=\relu(e(x))$. Depth and width are unrestricted
and weights are arbitrary reals.
\end{definition}

\begin{definition}[Subgradient oracle]\label{def:oracle}
$g:\R\to\R$ is a \emph{subgradient oracle} for $f:\R\to\R$ if $f(x)+g(x)(y-x)\le f(y)$ for all
$x,y$. This affine-minorant property is all the convergence analysis uses; it entails
convexity of $f$ and needs no differentiability.
\end{definition}

\begin{definition}[Iterations]
Fixed-step subgradient descent: $\theta_{k+1}=\theta_k-\eta g(\theta_k)$. Given the optimal
value $f^\star$, the \emph{Polyak step} is
\[
  \PS(x)=\begin{cases} x, & g(x)=0,\\[4pt]
  x-\dfrac{f(x)-f^\star}{g(x)^2}\,g(x), & g(x)\neq0,\end{cases}
  \qquad \theta_{k+1}=\PS(\theta_k).
\]
\end{definition}

\begin{definition}[Tropical $L^1$ training problem]
For residual targets $y_0,\dots,y_{N-1}$,
\[
  R(x)=\sum_{i=0}^{N-1}|x-y_i|,\qquad
  g(x)=\sum_{i=0}^{N-1}\operatorname{sgn}^{+}(x-y_i),\quad
  \operatorname{sgn}^{+}(u)=\begin{cases}+1,&u\ge0\\-1,&u<0.\end{cases}
\]
The trainable max-plus monomial is $M_\theta(z)=z\odot\theta=z+\theta$, and for data
$(X_i,Y_i)_{i<N}$ the empirical risk of a hypothesis $f$ is
$\mathcal R_N(f;X,Y)=\sum_{i<N}|f(X_i)-Y_i|$. With $y_i=Y_i-X_i$ one has
$\mathcal R_N(M_\theta;X,Y)=R(\theta)$ exactly.
\end{definition}

\begin{definition}[Sharpness]
$f$ is \emph{sharp with constant $\mu>0$ at $z$}, with $f^\star=f(z)$, if
$f^\star+\mu|x-z|\le f(x)$ for all $x$.
\end{definition}

\section{Quantitative Maslov dequantization}\label{sec:deq}

\begin{definition}[Smooth exp--log aggregator]
For $T>0$, $b\in\R$ and a list $\ell$,
$\LSE_T(b;\ell)=T\log\bigl(e^{b/T}+\sum_{y\in\ell}e^{y/T}\bigr)$.
\end{definition}

This is generated by the exp--log primitive $\eml(x,y)=e^{x}-\log y$: exponentials are
$\eml(\cdot,1)$ and logarithms are $1-\eml(0,\cdot)$, so
\[
  \LSE_T(b;\ell)=T\Bigl(1-\eml\bigl(0,\ \eml(b/T,1)+\textstyle\sum_{y\in\ell}\eml(y/T,1)\bigr)\Bigr),
\]
and the smooth aggregator is an exp--log expression in the strict sense.

\begin{theorem}[Lower dequantization bound]\label{thm:low}
For $T>0$, $\tmax(b;\ell)\le\LSE_T(b;\ell)$.
\end{theorem}
\begin{proof}
Let $M=\tmax(b;\ell)$. The maximum is attained by $b$ or by some element of $\ell$, so
$e^{M/T}$ occurs among the summands and the remaining summands are positive; hence
$e^{M/T}\le e^{b/T}+\sum_{y\in\ell}e^{y/T}$. Apply the increasing map $T\log(\cdot)$ and use
$M=T\cdot(M/T)$.
\end{proof}

\begin{theorem}[Upper bound with explicit error]\label{thm:up}
For $T>0$ and a list $\ell$ of length $r$,
$\LSE_T(b;\ell)\le\tmax(b;\ell)+T\log(r+1)$.
\end{theorem}
\begin{proof}
Every summand is at most $e^{M/T}$ with $M=\tmax(b;\ell)$, and there are $r+1$ of them, so
the sum is at most $(r+1)e^{M/T}$; apply $T\log(\cdot)$.
\end{proof}

\begin{corollary}
$\bigl|\LSE_T(b;\ell)-\tmax(b;\ell)\bigr|\le T\log(r+1)$, and
$\lim_{T\to0^{+}}\LSE_T(b;\ell)=\tmax(b;\ell)$ by squeezing between $\tmax(b;\ell)$ and
$\tmax(b;\ell)+T\log(r+1)$.
\end{corollary}

\begin{definition}[Exp--log neuron]
$\mathcal N_T^{b,\ell}(x)=\LSE_T\bigl(b_1x+b_2;\,[t_1x+t_2:t\in\ell]\bigr)$.
\end{definition}

\begin{theorem}[Uniform approximation rate]\label{thm:neuron}
For $T>0$ and all $x\in\R$,
$\bigl|\mathcal N_T^{b,\ell}(x)-P_{b,\ell}(x)\bigr|\le T\log k$ with $k=|\ell|+1$.
Consequently $\mathcal N_T^{b,\ell}\to P_{b,\ell}$ pointwise as $T\to0^{+}$, and the limit is
a tropical polynomial, hence tropical rational, hence computed exactly by a rectifier network.
\end{theorem}

The bound is uniform in $x$ and only logarithmic in the width: a layer of $k=1000$ units at
$T=10^{-3}$ is within $6.9\times10^{-3}$ of its tropical shadow everywhere on the line.

\begin{theorem}[Large-weight regime]
With $\LW_s(b;\ell)=s^{-1}\log\bigl(e^{sb}+\sum_{y\in\ell}e^{sy}\bigr)$ one has
$\LW_s(b;\ell)=\LSE_{1/s}(b;\ell)$ for $s>0$, hence
$\lim_{s\to\infty}\LW_s(b;\ell)=\tmax(b;\ell)$ with error at most $s^{-1}\log(r+1)$.
\end{theorem}
\begin{proof}
The substitution $T=1/s$ turns $y/T$ into $sy$ and $T\log(\cdot)$ into $s^{-1}\log(\cdot)$,
identifying the two expressions; then squeeze using Theorems~\ref{thm:low} and~\ref{thm:up}.
\end{proof}

\section{The tropical/rectifier dictionary in one variable}\label{sec:dict}

\begin{lemma}[Pairwise-sum product rule]\label{lem:prod}
For reals $b,b'$ and lists $\ell,\ell'$,
$\tmax(b;\ell)+\tmax(b';\ell')=\tmax(b+b';\mathcal S)$, where $\mathcal S$ is the list of all
pairwise sums $u+v$ with $u\in\{b\}\cup\ell$, $v\in\{b'\}\cup\ell'$, excluding the base pair
$b+b'$.
\end{lemma}
\begin{proof}
For $\le$: the two maxima are attained at some $u^\star,v^\star$, and $u^\star+v^\star$ belongs
to the pairwise-sum family. For $\ge$: any $u+v$ satisfies $u\le\tmax(b;\ell)$ and
$v\le\tmax(b';\ell')$.
\end{proof}

\begin{proposition}[Closure of tropical polynomials]
Tropical polynomial functions are closed under pointwise addition (tropical multiplication),
pointwise maximum (tropical addition), and multiplication by nonnegative scalars; they contain
all affine functions and all constants.
\end{proposition}

\begin{proposition}[Lattice-ordered vector space]\label{prop:lattice}
Tropical rational functions are closed under addition, negation, multiplication by arbitrary
real scalars, pointwise $\max$, pointwise $\min$, and $f\mapsto\relu\circ f$.
\end{proposition}
\begin{proof}
Write $f=P-Q$, $h=P'-Q'$. Addition: $f+h=(P+P')-(Q+Q')$, using Lemma~\ref{lem:prod}.
Negation: $-f=Q-P$. Scalars: for $c\ge0$, $cf=cP-cQ$; for $c<0$, $cf=-((-c)f)$. Maximum:
$\max(P-Q,P'-Q')=\max(P+Q',P'+Q)-(Q+Q')$. Minimum: $\min(f,h)=-\max(-f,-h)$. Rectifier:
$\relu(f)=\max(f,0)$ and constants are tropical polynomials.
\end{proof}

\begin{theorem}[Networks compute tropical rational functions]\label{thm:fwd}
Every rectifier expression evaluates to a tropical rational function.
\end{theorem}
\begin{proof}
Structural induction, using Proposition~\ref{prop:lattice} at each constructor: affine leaves
are tropical rational, and the constructors correspond to addition, scalar multiplication and
the rectifier.
\end{proof}

\begin{lemma}[Max as one rectifier]\label{lem:max}
$\max(u,v)=v+\relu(u-v)$.
\end{lemma}
\begin{proof}
If $u\le v$ both sides equal $v$; if $u\ge v$ both sides equal $u$.
\end{proof}

\begin{construction}\label{con:compile}
Define a rectifier expression by recursion on $\ell$:
\[
  E_{b,[\,]}=\mathrm{affine}(b_1,b_2),\qquad
  E_{b,\,t::\ell}=E_{b,\ell}+\mathrm{act}\bigl(\mathrm{affine}(t_1,t_2)+(-1)\cdot E_{b,\ell}\bigr).
\]
\end{construction}

\begin{theorem}\label{thm:compile}
$E_{b,\ell}(x)=P_{b,\ell}(x)$ for all $x$. Hence a tropical polynomial with $k$ monomials is
computed by a rectifier expression with exactly $k-1$ rectifier units, and a tropical rational
function $P_{b,\ell}-P_{b',\ell'}$ by $E_{b,\ell}+(-1)\cdot E_{b',\ell'}$ with
$|\ell|+|\ell'|$ rectifiers.
\end{theorem}
\begin{proof}
Induction on $\ell$, applying Lemma~\ref{lem:max} with $u=t_1x+t_2$ and $v=P_{b,\ell}(x)$.
\end{proof}

\begin{theorem}[Tropical/rectifier dictionary]\label{thm:dict}
$f:\R\to\R$ is tropical rational if and only if some rectifier expression $e$ satisfies
$e(x)=f(x)$ for all $x$.
\end{theorem}
\begin{proof}
($\Rightarrow$) Theorem~\ref{thm:compile}. ($\Leftarrow$) Theorem~\ref{thm:fwd}, together with
invariance of tropical rationality under pointwise equality.
\end{proof}

The correspondence is exact and cost-preserving: one rectifier per tropical monomial.

\begin{proposition}[Slope-Lipschitz bound]\label{prop:lip}
If all slopes of $P_{b,\ell}$ (including the base) satisfy $|t_1|\le L$, then
$|P_{b,\ell}(x)-P_{b,\ell}(y)|\le L|x-y|$.
\end{proposition}
\begin{proof}
Each piece obeys $t_1x+t_2\le t_1y+t_2+L|x-y|\le P_{b,\ell}(y)+L|x-y|$; take the maximum over
pieces and symmetrize.
\end{proof}

\begin{proposition}
$P_{b,\ell}$ is convex, being a pointwise maximum of affine functions.
\end{proposition}

\section{Sharpness of the tropical $L^1$ risk}\label{sec:sharp}

\begin{proposition}[The loss is itself tropical]\label{prop:losstrop}
$R(x)=\sum_{i<N}|x-y_i|$ is a tropical polynomial function of the parameter; hence it is
convex, piecewise linear with breakpoints at the $y_i$, and Lipschitz with constant $N$.
\end{proposition}
\begin{proof}
$|x-y|=\max(x-y,\,y-x)$ is a tropical polynomial with two monomials, and tropical polynomials
are closed under sums by Lemma~\ref{lem:prod}; induct on $N$ with the empty sum equal to $0$.
Expanding, $R$ is a maximum of $2^N$ affine functions with slopes in $\{-N,-N+2,\dots,N\}$;
apply Proposition~\ref{prop:lip}.
\end{proof}

\begin{proposition}[Subgradient oracle and bound]\label{prop:oracle}
$g(x)=\sum_{i<N}\operatorname{sgn}^{+}(x-y_i)$ is a subgradient oracle for $R$, and
$|g(x)|\le N$.
\end{proposition}
\begin{proof}
Termwise: if $y_i\le x$ then $|x-y_i|+(u-x)=u-y_i\le|u-y_i|$; if $y_i>x$ then
$|x-y_i|-(u-x)=y_i-u\le|u-y_i|$. Sum over $i$. The bound is the triangle inequality with each
term of modulus $1$.
\end{proof}

\begin{lemma}[Betweenness]\label{lem:between}
If $v$ lies between $u$ and $w$ (in either order) then
$|v-u|+|v-w|\le|x-u|+|x-w|$ for all $x$.
\end{lemma}
\begin{proof}
If $u\le v\le w$ the left side is $w-u$ and the right side is at least
$(x-u)+(w-x)=w-u$; the other order is symmetric.
\end{proof}

\begin{lemma}[Reflection identity]\label{lem:refl}
For $N=2m+1$, $\ 2R(x)=\sum_{i=0}^{2m}\bigl(|x-y_i|+|x-y_{2m-i}|\bigr)$.
\end{lemma}
\begin{proof}
The index reflection $i\mapsto 2m-i$ is an involution of $\{0,\dots,2m\}$, so the reflected sum
equals the original.
\end{proof}

\begin{theorem}[Sharpness / error bound]\label{thm:sharp}
Let $N=2m+1$ and $y_0\le y_1\le\cdots\le y_{2m}$, and put $\theta^\star=y_m$. Then for all
$x\in\R$,
\[
  R(\theta^\star)+|x-\theta^\star|\;\le\;R(x),
\]
i.e.\ $R$ is sharp at $\theta^\star$ with constant $\mu=1$.
\end{theorem}
\begin{proof}
For $i\in\{0,\dots,2m\}$ set
$G_i=\bigl(|x-y_i|+|x-y_{2m-i}|\bigr)-\bigl(|y_m-y_i|+|y_m-y_{2m-i}|\bigr)$.
Monotonicity gives that $y_m$ lies between $y_i$ and $y_{2m-i}$: if $i\le m$ then
$y_i\le y_m\le y_{2m-i}$, and if $i\ge m$ then $y_{2m-i}\le y_m\le y_i$. By
Lemma~\ref{lem:between}, $G_i\ge0$ for every $i$, while the diagonal index $i=m$ gives
$G_m=2|x-y_m|$. Retaining only the diagonal term among nonnegative summands and applying
Lemma~\ref{lem:refl} at $x$ and at $y_m$,
\[
  2|x-\theta^\star| = G_m \le \sum_{i=0}^{2m}G_i = 2R(x)-2R(\theta^\star).\qedhere
\]
\end{proof}

\begin{corollary}[Median optimality and uniqueness]\label{cor:median}
$R(\theta^\star)\le R(x)$ for all $x$, and every minimizer equals $\theta^\star$.
\end{corollary}
\begin{proof}
Optimality drops the nonnegative term. If $x$ is a minimizer then $R(x)\le R(\theta^\star)$,
so Theorem~\ref{thm:sharp} forces $|x-\theta^\star|\le0$.
\end{proof}

\begin{remark}
Sharpness is the piecewise-linear replacement for strong convexity. A $\mu$-strongly convex
function obeys the quadratic lower bound $f(x)\ge f^\star+\tfrac\mu2\|x-z\|^2$; the tropical
loss obeys the \emph{linear} bound $f(x)\ge f^\star+\mu\|x-z\|$, which is strictly stronger
near the optimum. Linear growth is what a nonsmooth first-order method can exploit.
\end{remark}

\begin{remark}[Sharpness never exceeds the slope]\label{rem:muG}
If $g$ is a subgradient oracle for $f$ with $|g|\le G$ and $f$ is sharp with constant $\mu$ at
$z$, then evaluating sharpness at $x=z+1$ gives $f^\star+\mu\le f(z+1)$, while the affine
minorant at $z+1$ evaluated at $z$ gives $f(z+1)\le f^\star+g(z+1)\le f^\star+G$. Hence
$\mu\le G$ and the \emph{tropical condition number} $\mu/G$ lies in $(0,1]$.
\end{remark}

\section{Fixed-step subgradient descent}\label{sec:fixed}

\begin{theorem}[One-step energy inequality]\label{thm:energy}
Let $g$ be a subgradient oracle for $f$ with $|g|\le G$, let $\eta\ge0$ and $z,x\in\R$. Then
\[
  (x-\eta g(x)-z)^2\;\le\;(x-z)^2-2\eta\bigl(f(x)-f(z)\bigr)+\eta^2G^2.
\]
\end{theorem}
\begin{proof}
Expand: $(x-\eta g(x)-z)^2=(x-z)^2-2\eta g(x)(x-z)+\eta^2g(x)^2$; use
$f(x)-f(z)\le g(x)(x-z)$ and $g(x)^2\le G^2$.
\end{proof}

\begin{theorem}[Telescoped bound]\label{thm:tel}
For the fixed-step iterates from $\theta_0=x_0$,
\[
  2\eta\sum_{k=0}^{n-1}\bigl(f(\theta_k)-f(z)\bigr)+(\theta_n-z)^2\;\le\;(x_0-z)^2+n\eta^2G^2.
\]
\end{theorem}
\begin{proof}
Induction on $n$, adding Theorem~\ref{thm:energy} at $x=\theta_n$ to the inductive hypothesis.
\end{proof}

\begin{theorem}[Best-iterate bound]\label{thm:best}
For $\eta>0$ and $n\ge1$ there is $k<n$ with
$f(\theta_k)-f(z)\le\bigl((x_0-z)^2+n\eta^2G^2\bigr)/(2\eta n)$.
\end{theorem}
\begin{proof}
If all $n$ gaps exceeded the bound $B$, summing would give
$nB<\sum_{k<n}(f(\theta_k)-f(z))$, contradicting Theorem~\ref{thm:tel} together with
$(\theta_n-z)^2\ge0$ and $2\eta nB=(x_0-z)^2+n\eta^2G^2$.
\end{proof}

\begin{theorem}[Optimal fixed step]\label{thm:sqrt}
Let $D=|x_0-z|>0$, $G>0$, $n\ge1$ and $\eta=D/(G\sqrt n)$. Then some $k<n$ satisfies
$f(\theta_k)\le f(z)+DG/\sqrt n$.
\end{theorem}
\begin{proof}
Substituting in Theorem~\ref{thm:best}, the numerator is $D^2+n\cdot\frac{D^2}{G^2n}G^2=2D^2$
and the denominator is $2Dn/(G\sqrt n)=2D\sqrt n/G$, with quotient $DG/\sqrt n$.
\end{proof}

\begin{corollary}[Tropical instance]
For the tropical $L^1$ loss, $G=N$, and with $\eta=|x_0-z|/(N\sqrt n)$ some iterate before
time $n$ satisfies $R(\theta_k)\le R(z)+|x_0-z|N/\sqrt n$ for any comparison parameter $z$.
\end{corollary}

\begin{theorem}[Parameter rate from sharpness]\label{thm:paramrate}
For an ordered odd sample with median $\theta^\star$, $\theta_0\ne\theta^\star$,
$D=|\theta_0-\theta^\star|$ and $\eta=D/(N\sqrt n)$, some $k<n$ satisfies simultaneously
\[
  R(\theta_k)\le R(\theta^\star)+\frac{DN}{\sqrt n}
  \qquad\text{and}\qquad
  |\theta_k-\theta^\star|\le\frac{DN}{\sqrt n}.
\]
\end{theorem}
\begin{proof}
Take $z=\theta^\star$ and combine with Theorem~\ref{thm:sharp}, which converts a risk gap of
$\varepsilon$ into a parameter error of at most $\varepsilon$.
\end{proof}

For a general convex nonsmooth loss, a small risk gap says nothing about proximity to the
argmin: the landscape may have a long flat valley. Sharpness forbids valleys and upgrades
every risk guarantee into a parameter guarantee at no cost.

\section{Polyak steps: geometric convergence}\label{sec:polyak}

\begin{theorem}[One-step contraction]\label{thm:contract}
Let $g$ be a subgradient oracle for $f$ with $|g|\le G$, $G>0$, and let $f$ be sharp with
constant $\mu>0$ at $z$, $f^\star=f(z)$. Then for all $x$,
\[
  \bigl(\PS(x)-z\bigr)^2\;\le\;\Bigl(1-\frac{\mu^2}{G^2}\Bigr)(x-z)^2 .
\]
\end{theorem}
\begin{proof}
By Remark~\ref{rem:muG}, $\mu\le G$, so $1-\mu^2/G^2\in[0,1)$.

\emph{Degenerate case $g(x)=0$.} The minorant property gives $f(x)\le f(z)=f^\star$, while
sharpness gives $f^\star+\mu|x-z|\le f(x)$; hence $x=z$, $\PS(x)=z$ and both sides vanish.

\emph{Main case $g(x)\ne0$.} Put $d=f(x)-f^\star\ge\mu|x-z|\ge0$ and $t=d/g(x)^2\ge0$, so
$\PS(x)=x-t\,g(x)$ and $t\,g(x)^2=d$. Expanding,
$(x-tg(x)-z)^2=(x-z)^2-2t\,g(x)(x-z)+t^2g(x)^2$. Convexity gives $d\le g(x)(x-z)$ and
$t^2g(x)^2=t\,d$, whence $(\PS(x)-z)^2\le(x-z)^2-t\,d$. Finally sharpness gives
$d^2\ge\mu^2(x-z)^2$ and $g(x)^2\le G^2$, so $t\,d=d^2/g(x)^2\ge\mu^2(x-z)^2/G^2$.
\end{proof}

\begin{theorem}[Geometric convergence]\label{thm:geom}
Under the hypotheses of Theorem~\ref{thm:contract}, the Polyak iterates from $\theta_0$
satisfy $(\theta_n-z)^2\le\bigl(1-\mu^2/G^2\bigr)^n(\theta_0-z)^2$ for all $n\ge0$, and
$\theta_n\to z$.
\end{theorem}
\begin{proof}
Induction on $n$, applying Theorem~\ref{thm:contract} at $\theta_n$ and multiplying the
inductive hypothesis by the nonnegative factor $1-\mu^2/G^2$. Since
$r=1-\mu^2/G^2\in[0,1)$, $r^n(\theta_0-z)^2\to0$ and a squeeze gives $|\theta_n-z|\to0$.
\end{proof}

\begin{theorem}[Linear rate for tropical training]\label{thm:troppolyak}
Let $N=2m+1$ with ordered residuals and median $\theta^\star=y_m$. Polyak-step subgradient
descent on the tropical $L^1$ risk satisfies, for every $n$,
\[
  (\theta_n-\theta^\star)^2\;\le\;\Bigl(1-\frac{1}{N^2}\Bigr)^{n}(\theta_0-\theta^\star)^2 ,
\]
and $\theta_n\to\theta^\star$. Consequently the trained model converges pointwise,
$M_{\theta_n}(z)\to M_{\theta^\star}(z)$ for every input $z$, to a tropical rational function
minimizing the tropical risk --- and by Theorem~\ref{thm:dict} to a function computed exactly
by a rectifier network.
\end{theorem}
\begin{proof}
Apply Theorems~\ref{thm:contract}--\ref{thm:geom} with $\mu=1$ (Theorem~\ref{thm:sharp}) and
$G=N$ (Proposition~\ref{prop:oracle}); pointwise convergence of the model is continuity of
$z+\cdot$.
\end{proof}

